import { assertEmptyRest } from './utils/assertUint8.mjs'
import { fromCompressInput } from './utils/input.mjs'
import { fromUint8Super } from './utils/output.mjs'

// Subimports are safe for pako, zlib-browserify does that
import { Deflate } from 'pako/lib/deflate.js'
import { Inflate } from 'pako/lib/inflate.js'
import msg from 'pako/lib/zlib/messages.js'

// We do this synchronously for now, should be fine for reasonable-sized input

const wrap =
  (Class, options) =>
  async (data, { format, ...rest } = {}) => {
    assertEmptyRest(rest)
    const chunks = fromCompressInput(data, Class === Deflate) // only compression can be called on strings
    const stream = new Class(options)
    for (const chunk of chunks) {
      // pako deflate in raw mode (deflateRaw here) fails on empty non-final chunks, so we must skip those
      if (chunk.length > 0) stream.push(chunk)
    }
    stream.push(Uint8Array.of(), true)
    if (stream.err) throw new Error(stream.msg || msg[stream.err])
    if (stream.strm.avail_in !== 0) {
      // We have data left after decompression
      // Node.js zlib and zlib-browserify does not always throw on that
      // Ref: https://github.com/nodejs/node/blob/264cad75ce08dabb6ddc8cc56c/src/node_zlib.cc#L1061-L1072
      // Ref: https://github.com/browserify/browserify-zlib/blob/8b3f0a862f6bb49/src/binding.js#L223-L234
      // paco sync methods never throw and just ignore any remaining input
      // Browsers throw on anything past the end, ref: https://compression.spec.whatwg.org/#decompression-stream
      // > If the end of the compressed input has not been reached, then throw a TypeError.
      // We throw too
      throw new TypeError('Junk found after end of compressed data.') // Replicate Chromium error
    }
    return fromUint8Super(stream.result, format)
  }

export const gzip = wrap(Deflate, { gzip: true })
export const gunzip = wrap(Inflate) // same as inflate, pako auto-detects
export const deflate = wrap(Deflate)
export const inflate = wrap(Inflate)
export const deflateRaw = wrap(Deflate, { raw: true })
export const inflateRaw = wrap(Inflate, { raw: true })
